#include <QCoreApplication>
#include <QBuffer>
#include <QDebug>
#include <QFile>
#include "repo-vul/src-vul/karchive/src/kzip.h"

int main(int argc, char *argv[])
{
    QCoreApplication app(argc, argv);

    // Read the PoC file
    QFile file("poc.kra");
    if (!file.open(QIODevice::ReadOnly)) {
        qWarning() << "Cannot open poc.kra";
        return 1;
    }
    QByteArray data = file.readAll();
    file.close();

    qDebug() << "Loaded" << data.size() << "bytes";

    // Create KZip on a buffer (like KraHandler does)
    QBuffer buffer(&data);
    buffer.open(QIODevice::ReadOnly);

    KZip zip(&buffer);
    // Use the public API - prepareArchive + openArchive is protected,
    // but we can use the device-based approach
    // Actually, let's just test the ZIP parsing directly

    // The crash happens in the destructor, so we just need to trigger
    // the parsing and let the object go out of scope

    qDebug() << "About to destroy KZip...";

    return 0;
}
EOF
